// ─── File: src/test/java/com/bank/dedup/DedupTest.java ───
package com.bank.dedup;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class DedupTest {

    @Test
    void linkedHashSet_dedupPreservesOrder() {
        List<String> txns = List.of("TXN-001", "TXN-002", "TXN-001", "TXN-003", "TXN-002");
        List<String> deduped = new ArrayList<>(new LinkedHashSet<>(txns));
        assertThat(deduped).containsExactly("TXN-001", "TXN-002", "TXN-003");
        // Duplicates removed, insertion order preserved!
    }

    @Test
    void stream_distinct() {
        List<String> txns = List.of("TXN-001", "TXN-002", "TXN-001", "TXN-003");
        List<String> deduped = txns.stream().distinct().toList();
        assertThat(deduped).containsExactly("TXN-001", "TXN-002", "TXN-003");
    }

    @Test
    void hashSet_losesOrder() {
        List<String> txns = List.of("C", "A", "B", "A", "C");
        Set<String> set = new HashSet<>(txns);
        // Order NOT guaranteed — could be any order!
        assertThat(set).containsExactlyInAnyOrder("A", "B", "C");
    }
}
```

