  class TradeDedupService {
      // preserves first-arrival order
      List<String> dedup(List<String> ids) {
          return new ArrayList<>(
              new LinkedHashSet<>(ids));
      }
      // stream equivalent
      List<String> dedupStream(List<String> ids){
          return ids.stream().distinct().toList();
      }
  }
  // LinkedHashSet internals:
  //   LinkedHashMap<E,PRESENT> backing map
  //   doubly-linked list threads entries
  //   add() → map.put(e,PRESENT) O(1)
  //   first put wins; later dupes ignored
  //   iteration = insertion order
